// TODO: generated by llm, rewrite later
const std = @import("std");

const c = @import("isocline_c");

const keywords = [_][]const u8{
    "+",
    "-",
    "*",
    "/",
    "%",
    "++",
    "=",
    ">",
    "<",
    ">=",
    "<=",
    "quote",
    "typeof",
    "cons",
    "car",
    "cdr",
    "write",
    "print",
    "input",
    "read",
    "symbol",
    "do",
    "cond",
    "eval",
    "def",
    "set!",
    "lambda",
    "dambda",
    "macro",
    "...",
};

const rainbow_colors = [_][*c]const u8{
    "#e06c75", // мягкий красный
    "#98c379", // мягкий зеленый
    "#d19a66", // мягкий оранжевый
    "#c678dd", // мягкий фиолетовый
    "#56b6c2", // мягкий бирюзовый
};

fn isLispIdLetter(ch: u8) bool {
    if (std.ascii.isAlphanumeric(ch)) return true;
    const lisp_syms = "-_?!*+/<=>%.~^:&";
    return std.mem.indexOfScalar(u8, lisp_syms, ch) != null;
}

fn isKeyword(word: []const u8) bool {
    for (keywords) |kw| {
        if (std.mem.eql(u8, word, kw)) return true;
    }
    return false;
}

fn isNumber(word: []const u8) bool {
    if (word.len == 0) return false;
    var start: usize = 0;

    if (word[0] == '-' or word[0] == '+') {
        if (word.len == 1) return false;
        start = 1;
    }

    var has_digit = false;
    var has_dot = false;

    for (word[start..]) |ch| {
        if (ch == '.') {
            if (has_dot) return false;
            has_dot = true;
        } else if (std.ascii.isDigit(ch)) {
            has_digit = true;
        } else {
            return false;
        }
    }

    return has_digit;
}

pub fn lispHighlighter(henv: ?*c.ic_highlight_env_t, input: [*c]const u8, arg: ?*anyopaque) callconv(.c) void {
    _ = arg;
    if (input == null) return;

    const input_len = std.mem.len(input);
    var i: usize = 0;
    var bracket_depth: usize = 0;

    while (i < input_len) {
        const current_char = input[i];

        if (current_char == '"') {
            var t: usize = 1;
            while (i + t < input_len) : (t += 1) {
                if (input[i + t] == '"' and input[i + t - 1] != '\\') {
                    t += 1;
                    break;
                }
            }
            c.ic_highlight(henv, @intCast(i), @intCast(t), "lisp-string");
            i += t;
        } else if (current_char == ';') {
            var t: usize = 1;
            while (i + t < input_len and input[i + t] != '\n') : (t += 1) {}
            c.ic_highlight(henv, @intCast(i), @intCast(t), "lisp-comment");
            i += t;
        } else if (current_char == '(') {
            const color = rainbow_colors[bracket_depth % rainbow_colors.len];
            c.ic_highlight(henv, @intCast(i), 1, color);
            bracket_depth += 1;
            i += 1;
        } else if (current_char == ')') {
            if (bracket_depth > 0) bracket_depth -= 1;
            const color = rainbow_colors[bracket_depth % rainbow_colors.len];
            c.ic_highlight(henv, @intCast(i), 1, color);
            i += 1;
        } else if (isLispIdLetter(current_char)) {
            var t: usize = 1;
            while (i + t < input_len and isLispIdLetter(input[i + t])) : (t += 1) {}

            const word = input[i .. i + t];

            if (isKeyword(word)) {
                c.ic_highlight(henv, @intCast(i), @intCast(t), "lisp-keyword");
            } else if (isNumber(word)) {
                c.ic_highlight(henv, @intCast(i), @intCast(t), "lisp-number");
            } else {
                c.ic_highlight(henv, @intCast(i), @intCast(t), null);
            }
            i += t;
        } else {
            c.ic_highlight(henv, @intCast(i), 1, null);
            i += 1;
        }
    }
}

pub fn enableLispHighlight() void {
    c.ic_style_def("lisp-keyword", "#61afef bold");
    c.ic_style_def("lisp-string", "#a9ffb4");
    c.ic_style_def("lisp-number", "#e5c07b");
    c.ic_style_def("lisp-comment", "#5c6370 it");

    c.ic_set_default_highlighter(lispHighlighter, null);
}
